#[test]
fn valid_registration_and_receipt_round_trip_through_json() {
    let registration = registration();
    let receipt = SupervisorLifecycleReceipt {
        supervisor_id: session().supervisor_id,
        session_id: session().session_id,
        worker_id: session().worker_id,
        occurred_at: 1_700_000_030,
        state: SupervisorWorkerState::Checkpointed,
        reason: None,
    };

    assert_eq!(registration.validate(), Ok(()));
    assert_eq!(session().validate(), Ok(()));
    assert_eq!(receipt.validate(), Ok(()));

    let registration_json = serde_json::to_string(&registration).expect("serialize registration");
    let receipt_json = serde_json::to_string(&receipt).expect("serialize receipt");

    assert_eq!(
        serde_json::from_str::<SupervisorRegistration>(&registration_json)
            .expect("deserialize registration"),
        registration
    );
    assert_eq!(
        serde_json::from_str::<SupervisorLifecycleReceipt>(&receipt_json)
            .expect("deserialize receipt"),
        receipt
    );
}

#[test]
fn blank_node_identity_is_refused() {
    let mut registration = registration();
    registration.identity.node_id = " ".to_string();

    assert_eq!(
        registration.validate(),
        Err(SupervisorError::EmptyField { field: "node_id" })
    );
}

#[test]
fn registration_requires_at_least_one_directive_capability() {
    let mut registration = registration();
    registration.capabilities.supported_directives.clear();

    assert_eq!(
        registration.validate(),
        Err(SupervisorError::NoDirectiveCapabilities)
    );
}

#[test]
fn duplicate_directive_capability_is_refused() {
    let mut registration = registration();
    registration
        .capabilities
        .supported_directives
        .push(SupervisorDirectiveCapability::Prompt);

    assert_eq!(
        registration.validate(),
        Err(SupervisorError::DuplicateDirectiveCapability {
            capability: SupervisorDirectiveCapability::Prompt,
        })
    );
}

#[test]
fn force_termination_flag_must_match_advertised_capability() {
    let mut registration = registration();
    registration
        .capabilities
        .supported_directives
        .push(SupervisorDirectiveCapability::TerminateForce);

    assert_eq!(
        registration.validate(),
        Err(SupervisorError::ForceTerminationMismatch {
            supports_force_termination: false,
            force_termination_advertised: true,
        })
    );
}

#[test]
fn ephemeral_outbox_cannot_claim_recovery_after_process_loss() {
    let mut registration = registration();
    registration.capabilities.outbox_durability = SupervisorOutboxDurability::Ephemeral;

    assert_eq!(
        registration.validate(),
        Err(SupervisorError::EphemeralOutboxCannotBeRecoverable)
    );
}

